-- Generated by Claude Code — Abstürze, Hänger und Leistungswerte aus der
-- iOS-App (Apple MetricKit). Die App liefert die Berichte selbst; es
-- werden keine Inhalte oder personenbezogenen Daten übertragen, nur
-- technische Diagnosen (Stacktraces, Zeiten) plus App-/OS-Version.
create table if not exists app_diagnostics (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('crash', 'hang', 'cpu', 'disk', 'launch', 'metrics')),
  app_version text,
  build text,
  os_version text,
  device text,
  summary text,
  payload jsonb not null,
  created_at timestamptz not null default now()
);
create index if not exists app_diagnostics_kind_time_idx on app_diagnostics (kind, created_at desc);

alter table app_diagnostics enable row level security;
-- Jede App-Sitzung (auch anonym) darf nur einfügen, nicht lesen.
create policy "App liefert Diagnosen" on app_diagnostics for insert to authenticated with check (true);
create policy "Redaktion sieht Diagnosen" on app_diagnostics for select using (is_admin_or_editor());

-- Für den täglichen Bericht: Abstürze/Hänger der letzten 24 h pro Version.
create or replace function public.app_diagnostics_summary()
returns jsonb
language sql
security definer
set search_path = public
stable
as $$
  select coalesce(jsonb_agg(row_to_json(t) order by t.count desc), '[]'::jsonb)
  from (
    select kind, coalesce(app_version, '?') || ' (' || coalesce(build, '?') || ')' as version, count(*) as count
    from app_diagnostics
    where created_at > now() - interval '24 hours' and kind in ('crash', 'hang', 'launch')
    group by 1, 2
  ) t;
$$;
revoke all on function public.app_diagnostics_summary() from public, anon, authenticated;
grant execute on function public.app_diagnostics_summary() to service_role;
